 fresh();{ClockGatingService service(api(),reinterpret_cast<dc_gpu*>(1),device);unavailable_register=0x2B409C;auto data=service.read(4);CHECK(data.families[2].support&&data.families[2].registers[0].available);CHECK(std::any_of(data.families[2].registers.begin(),data.families[2].registers.end(),[](const auto& r){return !r.available&&r.qualification=="access_denied";}));CHECK(service.apply(request(service,Family::second_level,Mode::disabled)).ok);CHECK(service.close().ok);}
 fresh();{ClockGatingService service(api(),reinterpret_cast<dc_gpu*>(1),device);service.read();stub=true;auto applied=service.apply(request(service,Family::engine,Mode::disabled));CHECK(!applied.ok&&service.needs_cleanup()&&requests==1);stub=false;CHECK(service.recover(Family::engine).ok&&objects.empty());}
 fresh();{ClockGatingService service(api(),reinterpret_cast<dc_gpu*>(1),device);service.read();CHECK(service.apply(request(service,Family::engine,Mode::disabled)).ok);free_fails=true;CHECK(!service.close().ok&&service.needs_cleanup()&&objects.size()==1);free_fails=false;CHECK(service.close().ok&&!service.needs_cleanup()&&objects.empty());}
 fresh();{ClockGatingService service(api(),reinterpret_cast<dc_gpu*>(1),device);service.read();parent++;CHECK(!service.apply(request(service,Family::engine,Mode::disabled)).ok&&allocations==0);parent--;const auto before=bind_calls;bind_failure=DC_ERR_IDENTITY;service.read(1);CHECK(bind_calls==before+1&&service.state().families[0].stale);}
