 fresh();{ClockGatingService service(api(),reinterpret_cast<dc_gpu*>(1),device);const auto established=service.read();const auto before=bind_calls;bind_failure=DC_ERR_INVALID;const auto data=service.read(1);CHECK(bind_calls==before+1);CHECK(data.families[0].availability==VoltagePolicyAvailability::invalid&&data.families[0].stale);CHECK(data.families[0].binding==established.families[0].binding&&data.families[0].supported_engines==established.families[0].supported_engines&&data.families[0].eligible_engines==established.families[0].eligible_engines);CHECK(data.families[1].availability==VoltagePolicyAvailability::available&&!data.families[1].stale&&data.families[1].binding==established.families[1].binding);CHECK(allocations==0&&pcie_sets==0);}
